const pageStyles = "@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700;800&family=Inter:wght@400;500;600;700&display=swap');\n\n  :root{\n    --black:#0A0A0C;\n    --black-2:#131316;\n    --black-3:#1B1B1F;\n    --paper:#F7F6F2;\n    --white:#FFFFFF;\n    --ink:#EDECE8;\n    --muted:#A6A4A0;\n    --muted-2:#6B6A66;\n    --yellow:#FCB813;\n    --yellow-dim:#B98A12;\n    --purple:#4B297E;\n    --purple-bright:#8B5CF6;\n    --line: rgba(255,255,255,0.09);\n    --line-dark: rgba(10,10,12,0.10);\n    --radius: 22px;\n    --radius-sm: 14px;\n    --maxw: 1180px;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html{scroll-behavior:smooth;}\n  body{\n    background:var(--black);\n    color:var(--ink);\n    font-family:'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;\n    -webkit-font-smoothing:antialiased;\n    overflow-x:hidden;\n  }\n  img{max-width:100%; display:block;}\n  a{color:inherit; text-decoration:none;}\n  .wrap{max-width:var(--maxw); margin:0 auto; padding:0 28px;}\n  h1,h2,h3,h4{\n    font-family:'Barlow Condensed', sans-serif;\n    font-weight:800;\n    text-transform:uppercase;\n    letter-spacing:0.01em;\n    line-height:0.98;\n  }\n  .eyebrow{\n    font-family:'Inter', sans-serif;\n    font-weight:600;\n    font-size:12.5px;\n    letter-spacing:0.16em;\n    text-transform:uppercase;\n    color:var(--yellow);\n    display:flex;\n    align-items:center;\n    gap:10px;\n    margin-bottom:18px;\n  }\n  .eyebrow::before{\n    content:'';\n    width:22px; height:2px;\n    background:var(--yellow);\n    display:inline-block;\n  }\n  .btn{\n    display:inline-flex;\n    align-items:center;\n    gap:10px;\n    padding:15px 28px;\n    border-radius:100px;\n    font-family:'Inter', sans-serif;\n    font-weight:600;\n    font-size:15px;\n    cursor:pointer;\n    border:1px solid transparent;\n    transition:transform 0.25s ease, box-shadow 0.25s ease, background 0.25s ease;\n    white-space:nowrap;\n  }\n  .btn:hover{ transform:translateY(-2px); }\n  .btn-primary{\n    background:var(--yellow);\n    color:var(--black);\n  }\n  .btn-primary:hover{ box-shadow:0 12px 28px rgba(252,184,19,0.28); }\n  .btn-ghost{\n    background:transparent;\n    color:var(--ink);\n    border:1px solid var(--line);\n  }\n  .btn-ghost:hover{ border-color:rgba(255,255,255,0.3); background:rgba(255,255,255,0.03); }\n  .btn-dark{\n    background:var(--black);\n    color:var(--white);\n  }\n  .btn-dark:hover{ box-shadow:0 12px 28px rgba(0,0,0,0.28); }\n\n  /* ---------- NAV ---------- */\n  header{\n    position:fixed; top:0; left:0; right:0; z-index:100;\n    padding:18px 0;\n    transition:background 0.35s ease, padding 0.35s ease, border-color .35s ease;\n    border-bottom:1px solid transparent;\n  }\n  header.scrolled{\n    background:rgba(10,10,12,0.82);\n    backdrop-filter:blur(14px);\n    -webkit-backdrop-filter:blur(14px);\n    padding:12px 0;\n    border-bottom-color:var(--line);\n  }\n  nav{ display:flex; align-items:center; justify-content:space-between; gap:24px; }\n  .logo-mark{ height:90px !important; width:auto !important; max-width:none !important; }\n  .nav-links{ display:flex; align-items:center; gap:34px; font-size:14.5px; font-weight:500; color:var(--muted); }\n  .nav-links a{ transition:color 0.2s ease; }\n  .nav-links a:hover{ color:var(--white); }\n  .nav-cta{ display:flex; align-items:center; gap:16px; }\n  .nav-cta .btn{ padding:10px 20px; font-size:13.5px; }\n  .nav-toggle{ display:none; background:none; border:none; color:var(--white); cursor:pointer; }\n\n  /* ---------- HERO ---------- */\n  .hero{\n    position:relative;\n    padding:168px 0 96px;\n    overflow:hidden;\n    background:\n      radial-gradient(60% 55% at 82% 8%, rgba(75,41,126,0.45), transparent 60%),\n      radial-gradient(50% 45% at 10% 95%, rgba(252,184,19,0.10), transparent 60%),\n      var(--black);\n  }\n  .hero-grid{ display:grid; grid-template-columns:1.15fr 0.85fr; gap:48px; align-items:end; }\n  .hero h1{\n    font-size:clamp(46px, 6.6vw, 92px);\n    color:var(--white);\n  }\n  .hero h1 .accent{ color:var(--yellow); }\n  .hero-sub{\n    margin-top:26px;\n    max-width:480px;\n    font-size:17.5px;\n    line-height:1.6;\n    color:var(--muted);\n  }\n  .hero-actions{ display:flex; gap:14px; margin-top:38px; flex-wrap:wrap; }\n  .hero-trust{\n    font-family:'Barlow Condensed', sans-serif;\n    font-weight:700;\n    font-size:17px;\n    text-transform:none;\n    line-height:1.3;\n    color:var(--muted);\n    margin-top:34px;\n    padding-top:22px;\n    border-top:1px solid var(--line);\n    max-width:420px;\n  }\n  .hero-trust span{ color:var(--yellow); }\n\n  /* ---- hero visual: mockup flotante + badge ---- */\n  .hero-visual{\n    position:relative;\n    min-height:420px;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n  }\n  .hero-glow{\n    position:absolute; width:340px; height:340px; border-radius:50%;\n    background:radial-gradient(circle, rgba(252,184,19,0.16), transparent 70%);\n    filter:blur(10px);\n    top:10%; left:50%; transform:translateX(-50%);\n  }\n  .device-mock{\n    position:relative;\n    width:300px;\n    background:var(--black-2);\n    border:1px solid var(--line);\n    border-radius:24px;\n    padding:20px 20px 24px;\n    box-shadow:0 40px 80px rgba(0,0,0,0.55);\n    transform:rotate(3deg);\n  }\n  .device-topbar{\n    display:flex; justify-content:space-between; align-items:center;\n    margin-bottom:18px; padding-bottom:14px; border-bottom:1px solid var(--line);\n  }\n  .device-name{ font-size:13px; font-weight:700; color:var(--white); }\n  .device-live{ font-size:10.5px; color:#4ADE80; font-weight:600; }\n  .device-msg{\n    font-size:12.5px; line-height:1.4; padding:10px 14px; border-radius:14px;\n    max-width:85%; margin-bottom:10px;\n  }\n  .device-msg.in{ background:var(--black-3); color:var(--ink); border-bottom-left-radius:4px; }\n  .device-msg.out{\n    background:var(--yellow); color:var(--black); font-weight:600;\n    margin-left:auto; border-bottom-right-radius:4px;\n  }\n  .device-chip{\n    margin-top:14px; display:inline-block;\n    background:rgba(139,92,246,0.14); border:1px solid var(--purple-bright);\n    color:#C9B6FF; font-size:11px; font-weight:600;\n    padding:7px 12px; border-radius:100px;\n  }\n  .float-badge{\n    position:absolute; bottom:-6px; left:-18px;\n    background:var(--yellow); color:var(--black);\n    border-radius:16px; padding:16px 20px;\n    box-shadow:0 20px 40px rgba(252,184,19,0.25);\n    display:flex; flex-direction:column;\n  }\n  .float-badge strong{\n    font-family:'Barlow Condensed', sans-serif; font-weight:800; font-size:28px; line-height:1;\n  }\n  .float-badge span{ font-size:11px; font-weight:600; margin-top:4px; max-width:120px; }\n\n  /* ---- stats bar ---- */\n  .statsbar{\n    background:var(--black-2);\n    border-bottom:1px solid var(--line);\n    padding:56px 0;\n  }\n  .statsbar-grid{\n    display:grid; grid-template-columns:repeat(4, 1fr); gap:32px;\n  }\n  .stat-item{\n    padding-top:16px; border-top:2px solid var(--yellow);\n  }\n  .stat-item strong{\n    display:block; font-family:'Barlow Condensed', sans-serif; font-weight:800;\n    font-size:38px; color:var(--white);\n  }\n  .stat-item span{ font-size:13px; color:var(--muted); line-height:1.4; }\n\n  /* marquee */\n  .marquee-wrap{\n    border-top:1px solid var(--line);\n    border-bottom:1px solid var(--line);\n    padding:26px 0;\n    background:var(--black-2);\n    overflow:hidden;\n  }\n  .marquee-track{\n    display:flex; gap:64px; white-space:nowrap;\n    animation:scroll 32s linear infinite;\n    width:max-content;\n  }\n  .marquee-track span{\n    font-family:'Barlow Condensed', sans-serif;\n    font-weight:700;\n    font-size:19px;\n    letter-spacing:0.02em;\n    color:var(--muted-2);\n    text-transform:uppercase;\n  }\n  @keyframes scroll{\n    from{ transform:translateX(0); }\n    to{ transform:translateX(-50%); }\n  }\n\n  /* ---------- SECTION SHARED ---------- */\n  section{ padding:118px 0; position:relative; }\n  .section-head{\n    display:flex; justify-content:space-between; align-items:flex-end;\n    gap:32px; margin-bottom:56px; flex-wrap:wrap;\n  }\n  .section-head h2{ font-size:clamp(34px, 4.4vw, 56px); }\n  .section-head p{ max-width:380px; color:var(--muted); font-size:15.5px; line-height:1.6; }\n  .light h2, .light .eyebrow{ color:var(--black); }\n  .light .eyebrow{ color:var(--purple); }\n  .light .eyebrow::before{ background:var(--purple); }\n  .light .section-head p{ color:var(--muted-2); }\n\n  /* ---------- SISTEMA (signature) ---------- */\n  .sistema{ background:var(--black); }\n  .sistema-diagram{\n    margin-top:20px;\n    position:relative;\n    padding:52px 12px 12px;\n  }\n  .sistema-line{\n    position:absolute;\n    top:96px; left:0; right:0; height:2px;\n  }\n  .sistema-line svg{ width:100%; height:2px; display:block; }\n  .sistema-steps{\n    display:grid;\n    grid-template-columns:repeat(4, 1fr);\n    gap:24px;\n    position:relative;\n    z-index:2;\n  }\n  .sistema-step{ text-align:left; }\n  .sistema-dot{\n    width:14px; height:14px; border-radius:50%;\n    background:var(--yellow);\n    box-shadow:0 0 0 6px rgba(252,184,19,0.14);\n    margin-bottom:18px;\n  }\n  .sistema-step:nth-child(2) .sistema-dot{ background:var(--purple-bright); box-shadow:0 0 0 6px rgba(139,92,246,0.16); }\n  .sistema-step:nth-child(3) .sistema-dot{ background:var(--yellow); box-shadow:0 0 0 6px rgba(252,184,19,0.14); }\n  .sistema-step:nth-child(4) .sistema-dot{ background:var(--purple-bright); box-shadow:0 0 0 6px rgba(139,92,246,0.16); }\n  .sistema-num{ font-size:12px; color:var(--muted-2); font-weight:600; letter-spacing:0.1em; }\n  .sistema-step h4{\n    font-size:23px; margin-top:8px; margin-bottom:10px; color:var(--white);\n  }\n  .sistema-step p{ font-size:14.5px; color:var(--muted); line-height:1.55; max-width:230px; }\n\n  /* ---------- SERVICIOS (bento, clicable) ---------- */\n  .servicios{ background:var(--paper); color:var(--black); }\n  .bento-grid{\n    display:grid;\n    grid-template-columns:repeat(4, 1fr);\n    grid-auto-flow:dense;\n    grid-auto-rows:1fr;\n    gap:16px;\n  }\n  .bento-card{\n    background:var(--black-2);\n    border:1px solid rgba(255,255,255,0.08);\n    border-radius:20px;\n    padding:28px 26px;\n    display:flex; flex-direction:column;\n    text-decoration:none; color:inherit;\n    transition:transform .25s ease, border-color .25s ease, background .25s ease;\n  }\n  .bento-card:hover{\n    transform:translateY(-5px);\n    border-color:var(--yellow);\n    background:var(--black-3);\n  }\n  .bento-card.featured{\n    grid-column:span 2; grid-row:span 2;\n    background:linear-gradient(160deg, #241A3D 0%, #14101F 100%);\n    border-color:var(--purple-bright);\n    padding:36px 34px;\n  }\n  .bento-card.featured:hover{ border-color:var(--yellow); }\n  .bento-icon{\n    width:52px; height:52px;\n    display:flex; align-items:center; justify-content:center;\n    border-radius:50%;\n    background:var(--yellow);\n    color:var(--black);\n    margin-bottom:20px;\n    flex:none;\n  }\n  .bento-card.featured .bento-icon{ width:64px; height:64px; }\n  .bento-tag{\n    display:inline-block; margin-bottom:12px; font-size:11px; font-weight:700;\n    color:var(--yellow); letter-spacing:0.06em; text-transform:uppercase;\n  }\n  .bento-card h3{\n    font-size:17.5px; text-transform:none; font-weight:700; letter-spacing:0;\n    color:var(--white); margin-bottom:10px; line-height:1.18;\n  }\n  .bento-card.featured h3{ font-size:27px; }\n  .bento-card p{ font-size:13.5px; color:var(--muted); line-height:1.55; margin-bottom:18px; flex:1; }\n  .bento-card.featured p{ font-size:15px; max-width:320px; }\n  .bento-arrow{ font-size:12.5px; font-weight:700; color:var(--yellow); margin-top:auto; }\n\n  /* ---------- MEDICO ---------- */\n  .medico{\n    background:linear-gradient(135deg, #1B1330 0%, #0A0A0C 55%);\n    border-top:1px solid var(--line);\n    border-bottom:1px solid var(--line);\n  }\n  .medico-grid{ display:grid; grid-template-columns:1fr 1fr; gap:64px; align-items:center; }\n  .medico h2{ font-size:clamp(32px,4vw,48px); color:var(--white); margin-bottom:22px; }\n  .medico p{ color:var(--muted); font-size:16px; line-height:1.7; margin-bottom:28px; max-width:460px; }\n  .medico-list{ display:flex; flex-direction:column; gap:14px; margin-bottom:30px; }\n  .medico-list div{\n    display:flex; align-items:center; gap:12px; font-size:14.5px; color:var(--ink);\n  }\n  .medico-list div::before{\n    content:''; width:6px; height:6px; border-radius:50%; background:var(--yellow); flex:none;\n  }\n  .medico-card{\n    background:var(--black-3);\n    border:1px solid var(--line);\n    border-radius:var(--radius);\n    padding:36px;\n  }\n  .medico-stat{\n    display:flex; align-items:baseline; gap:10px; margin-bottom:22px;\n    padding-bottom:22px; border-bottom:1px solid var(--line);\n  }\n  .medico-stat:last-child{ border-bottom:none; margin-bottom:0; padding-bottom:0; }\n  .medico-stat strong{\n    font-family:'Barlow Condensed', sans-serif; font-weight:800; font-size:40px; color:var(--yellow);\n  }\n  .medico-stat span{ font-size:13.5px; color:var(--muted); line-height:1.4; }\n\n  /* ---------- PLANES ---------- */\n  .planes{ background:var(--black); }\n  .plan-appgrid{\n    display:grid; grid-template-columns:repeat(2, 1fr); gap:14px;\n  }\n  @media (min-width: 700px){\n    .plan-appgrid{ grid-template-columns:repeat(4, 1fr); gap:18px; }\n  }\n  .plan-appcard{\n    display:flex; flex-direction:column; align-items:flex-start; gap:10px;\n    background:var(--black-2); border:1px solid var(--line); border-radius:18px;\n    padding:22px 18px; text-decoration:none; color:inherit;\n    transition:transform .25s ease, border-color .25s ease, background .25s ease;\n  }\n  .plan-appcard:hover{ transform:translateY(-4px); border-color:rgba(255,255,255,0.25); background:var(--black-3); }\n  .plan-appcard.featured{ border-color:var(--purple-bright); background:linear-gradient(160deg, #241A3D 0%, #14101F 100%); }\n  .plan-appicon{\n    width:42px; height:42px; border-radius:12px;\n    background:var(--yellow); color:var(--black);\n    display:flex; align-items:center; justify-content:center; flex:none;\n  }\n  .plan-appcard h3{\n    font-size:15.5px; font-weight:800; color:var(--white); line-height:1.15;\n  }\n  .plan-appcard p{\n    font-size:12px; color:var(--muted); line-height:1.4; margin-bottom:4px;\n  }\n  .plan-appcard .arrow{\n    margin-top:auto; font-size:12px; font-weight:600; color:var(--yellow);\n  }\n  .plan-grid{ display:grid; grid-template-columns:repeat(3, 1fr); gap:22px; }\n  .plan-grid-2{ grid-template-columns:repeat(2, 1fr); max-width:900px; }\n  .plan-grid-1{ grid-template-columns:1fr; max-width:420px; }\n  .plan-card{\n    background:var(--black-2);\n    border:1px solid var(--line);\n    border-radius:var(--radius);\n    padding:38px 32px;\n    display:flex; flex-direction:column;\n    transition:transform .3s ease, border-color .3s ease;\n  }\n  .plan-card:hover{ transform:translateY(-6px); border-color:rgba(255,255,255,0.22); }\n  .plan-card.featured{\n    background:linear-gradient(160deg, #241A3D 0%, #14101F 100%);\n    border-color:var(--purple-bright);\n    position:relative;\n  }\n  .plan-badge{\n    position:absolute; top:-13px; right:32px;\n    background:var(--yellow); color:var(--black);\n    font-size:11.5px; font-weight:700; letter-spacing:0.05em;\n    padding:6px 14px; border-radius:100px; text-transform:uppercase;\n  }\n  .plan-name{ font-size:15px; color:var(--muted); text-transform:uppercase; letter-spacing:0.08em; font-weight:600; margin-bottom:14px; }\n  .plan-price{\n    font-family:'Barlow Condensed', sans-serif; font-weight:800; font-size:46px; color:var(--white);\n    margin-bottom:4px;\n  }\n  .plan-price span{ font-size:15px; font-family:'Inter',sans-serif; font-weight:500; color:var(--muted-2); text-transform:none; }\n  .plan-price.plan-price-quote{\n    font-weight:700; font-size:22px; text-transform:none; margin-bottom:20px;\n  }\n  .plan-desc{ font-size:14px; color:var(--muted); margin-bottom:26px; line-height:1.5; }\n  .plan-features{ list-style:none; display:flex; flex-direction:column; gap:13px; margin-bottom:30px; flex:1; }\n  .plan-features li{\n    font-size:14px; color:var(--ink); display:flex; gap:10px; align-items:flex-start; line-height:1.4;\n  }\n  .plan-features li::before{ content:'—'; color:var(--yellow); flex:none; }\n  .plan-card .btn{ justify-content:center; width:100%; }\n\n  /* ---------- TESTIMONIOS ---------- */\n  .testi{ background:var(--paper); color:var(--black); }\n  .testi-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:22px; }\n  .testi-card{\n    background:var(--white);\n    border-radius:var(--radius-sm);\n    padding:30px 28px;\n    border:1px solid var(--line-dark);\n  }\n  .testi-stars{ color:var(--yellow-dim); font-size:14px; letter-spacing:2px; margin-bottom:16px; }\n  .testi-card p{ font-size:15px; line-height:1.6; color:#3A3936; margin-bottom:22px; }\n  .testi-who{ display:flex; flex-direction:column; }\n  .testi-who strong{ font-size:14.5px; }\n  .testi-who span{ font-size:12.5px; color:var(--muted-2); }\n\n  /* ---------- CTA ---------- */\n  .cta{\n    background:var(--yellow);\n    color:var(--black);\n    padding:110px 0;\n  }\n  .cta-grid{ display:flex; justify-content:space-between; align-items:center; gap:40px; flex-wrap:wrap; }\n  .cta h2{ font-size:clamp(36px,5vw,64px); max-width:640px; }\n  .cta-actions{ display:flex; gap:14px; flex-wrap:wrap; }\n\n  /* ---------- FOOTER ---------- */\n  footer{ background:var(--black); padding:70px 0 30px; border-top:1px solid var(--line); }\n  .foot-grid{\n    display:grid; grid-template-columns:1.4fr 1fr 1fr 1fr; gap:40px;\n    padding-bottom:50px; border-bottom:1px solid var(--line);\n  }\n  .foot-logo{ height:26px; margin-bottom:18px; }\n  .foot-grid p{ color:var(--muted); font-size:14px; max-width:280px; line-height:1.6; }\n  .foot-col h5{\n    font-family:'Inter',sans-serif; font-size:12.5px; text-transform:uppercase; letter-spacing:0.1em;\n    color:var(--muted-2); font-weight:600; margin-bottom:18px;\n  }\n  .foot-col a{\n    display:block; color:var(--ink); font-size:14.5px; margin-bottom:12px; transition:color .2s ease;\n  }\n  .foot-col a:hover{ color:var(--yellow); }\n  .foot-bottom{\n    display:flex; justify-content:space-between; align-items:center; padding-top:26px;\n    font-size:13px; color:var(--muted-2); flex-wrap:wrap; gap:12px;\n  }\n\n  /* ---------- WHATSAPP FLOAT ---------- */\n  .wa-float{\n    position:fixed; bottom:26px; right:26px; z-index:90;\n    width:58px; height:58px; border-radius:50%;\n    background:#25D366;\n    display:flex; align-items:center; justify-content:center;\n    box-shadow:0 10px 26px rgba(0,0,0,0.35);\n    transition:transform .25s ease;\n  }\n  .wa-float:hover{ transform:scale(1.08); }\n\n  /* ---------- reveal ---------- */\n  .reveal{ opacity:0; transform:translateY(24px); transition:opacity .7s ease, transform .7s ease; }\n  .reveal.in{ opacity:1; transform:translateY(0); }\n\n  /* ---------- RESPONSIVE ---------- */\n  @media (max-width: 900px){\n    .logo-mark{ height:58px !important; width:auto !important; max-width:none !important; }\n    .nav-cta .btn{ padding:8px 14px; font-size:12px; gap:0; }\n    .nav-links{ display:none; }\n    .nav-toggle{ display:block; }\n    .hero-grid{ grid-template-columns:1fr; gap:56px; }\n    .hero-visual{ min-height:340px; }\n    .device-mock{ transform:rotate(0deg); }\n    .float-badge{ left:8px; }\n    .statsbar-grid{ grid-template-columns:1fr 1fr; row-gap:28px; }\n    .sistema-steps{ grid-template-columns:1fr 1fr; row-gap:36px; }\n    .sistema-line{ display:none; }\n    .bento-grid{ grid-template-columns:1fr; }\n    .bento-card.featured{ grid-column:span 1; grid-row:span 1; }\n    .medico-grid{ grid-template-columns:1fr; }\n    .plan-grid{ grid-template-columns:1fr; }\n    .testi-grid{ grid-template-columns:1fr; }\n    .foot-grid{ grid-template-columns:1fr 1fr; }\n    .cta-grid{ flex-direction:column; align-items:flex-start; }\n  }\n  @media (max-width: 560px){\n    section{ padding:78px 0; }\n    .hero{ padding:140px 0 64px; }\n    .foot-grid{ grid-template-columns:1fr; }\n    .sistema-steps{ grid-template-columns:1fr; }\n    .statsbar-grid{ grid-template-columns:1fr 1fr; gap:24px; }\n    .device-mock{ width:260px; }\n  }\n\n  /* ======================================================\n     PREVIEW BANNER\n  ====================================================== */\n  .preview-banner{\n    background:var(--yellow); color:var(--black); text-align:center;\n    font-family:'Inter',sans-serif; font-weight:700; font-size:13px;\n    padding:10px; letter-spacing:0.02em;\n  }\n\n  /* ======================================================\n     HEADER CÁPSULA (solo para este preview)\n  ====================================================== */\n  .header-v2{ position:relative; z-index:50; padding:26px 0; }\n  .nav-v2{ display:flex; align-items:center; justify-content:space-between; }\n  .nav-v2-pill{\n    display:flex; align-items:center; gap:36px;\n    background:rgba(255,255,255,0.04); border:1px solid var(--line);\n    border-radius:100px; padding:12px 34px;\n  }\n  .nav-v2-pill a{ font-size:14px; color:var(--muted); font-weight:500; }\n  .nav-v2-pill a:hover{ color:var(--white); }\n  .nav-v2-cta{\n    background:var(--yellow); color:var(--black); font-weight:700; font-size:13.5px;\n    padding:13px 26px; border-radius:100px; display:inline-flex; align-items:center; gap:8px;\n  }\n\n  /* ======================================================\n     HERO v2 — diagonal, fiel a composición\n  ====================================================== */\n  .hero-v2{\n    position:relative; overflow:hidden; padding:40px 0 80px;\n    background: linear-gradient(180deg, #0A0A0C 0%, #16161A 55%, #232320 100%);\n  }\n  .hero-v2-grid{ display:grid; grid-template-columns:1.05fr 0.95fr; gap:40px; align-items:center; margin-top:30px; }\n  .hero-v2-pillbadge{\n    display:inline-block; font-size:12.5px; font-weight:700; color:var(--yellow);\n    letter-spacing:0.03em; margin-bottom:18px;\n  }\n  .hero-v2 h1{ font-size:clamp(38px,5vw,58px); color:var(--white); margin-bottom:18px; line-height:1.04; }\n  .hero-v2-sub{ font-size:15.5px; line-height:1.65; color:var(--muted); max-width:420px; margin-bottom:30px; }\n  .hero-v2-actions{ display:flex; align-items:center; gap:16px; margin-bottom:36px; }\n  .hero-v2-play{\n    width:44px; height:44px; border-radius:50%; border:1px solid var(--line);\n    display:flex; align-items:center; justify-content:center; color:var(--white); flex:none;\n  }\n  .hero-v2-trustrow{ display:flex; align-items:center; gap:34px; }\n  .hero-v2-rating{ display:flex; align-items:center; gap:10px; }\n  .hero-v2-rating .num{ font-family:'Barlow Condensed',sans-serif; font-weight:800; font-size:30px; color:var(--white); }\n  .hero-v2-rating .stars{ color:var(--yellow); font-size:12px; letter-spacing:1px; }\n  .hero-v2-rating .lbl{ font-size:11px; color:var(--muted-2); line-height:1.3; }\n  .hero-v2-team{ display:flex; align-items:center; gap:10px; }\n  .hero-v2-team-label{ font-size:11px; color:var(--muted-2); }\n  .hero-v2-avatars{ display:flex; }\n  .hero-v2-avatars span{\n    width:32px; height:32px; border-radius:50%; background:var(--black-3);\n    border:2px solid #16161A; margin-left:-9px;\n    display:flex; align-items:center; justify-content:center;\n    font-family:'Barlow Condensed',sans-serif; font-weight:800; font-size:11px; color:var(--yellow);\n  }\n  .hero-v2-avatars span:first-child{ margin-left:0; }\n\n  /* stage diagonal de teléfonos */\n  .phone-stage-v2{ position:relative; height:540px; }\n  .phone-v2{\n    position:absolute; width:216px; height:440px;\n    background:var(--black-2); border:7px solid #2A2A30; border-radius:34px;\n    box-shadow:0 40px 80px rgba(0,0,0,0.5); overflow:hidden;\n  }\n  .phone-v2-a{ top:0; left:110px; z-index:3; transform:rotate(9deg); }\n  .phone-v2-b{ top:60px; left:250px; z-index:2; transform:rotate(9deg); opacity:0.85; }\n  .phone-v2-c{ top:290px; left:10px; z-index:1; transform:rotate(-14deg); opacity:0.5; width:170px; height:340px; }\n  .phone-v2-notch{ position:absolute; top:0; left:50%; transform:translateX(-50%); width:64px; height:16px; background:#2A2A30; border-radius:0 0 10px 10px; z-index:3; }\n  .phone-v2-screen{ padding:30px 12px 12px; height:100%; display:flex; flex-direction:column; gap:9px; }\n  .phone-v2-card{ background:var(--black-3); border:1px solid rgba(255,255,255,0.07); border-radius:11px; padding:11px; }\n  .phone-v2-card .row{ display:flex; justify-content:space-between; font-size:9.5px; color:var(--muted); font-weight:600; margin-bottom:6px; }\n  .phone-v2-card .big{ font-family:'Barlow Condensed',sans-serif; font-weight:800; font-size:23px; color:var(--white); }\n  .phone-v2-bars{ display:flex; align-items:flex-end; gap:3px; height:32px; margin-top:6px; }\n  .phone-v2-bars i{ flex:1; border-radius:2px 2px 0 0; background:linear-gradient(180deg,var(--yellow),var(--yellow-dim)); }\n\n  .float-bubble-v2{\n    position:absolute; top:10px; left:0; z-index:4;\n    background:rgba(19,19,22,0.94); backdrop-filter:blur(6px);\n    border:1px solid var(--line); border-radius:14px; padding:11px 15px;\n    display:flex; gap:9px; align-items:flex-start; max-width:200px;\n  }\n  .float-bubble-v2 .ck{\n    width:18px; height:18px; border-radius:50%; background:var(--yellow); color:var(--black);\n    display:flex; align-items:center; justify-content:center; flex:none; font-size:11px; font-weight:800; margin-top:1px;\n  }\n  .float-bubble-v2 p{ font-size:11px; color:var(--ink); line-height:1.35; }\n  .float-badge-v2{\n    position:absolute; bottom:30px; right:10px; z-index:4;\n    background:var(--yellow); color:var(--black); border-radius:16px;\n    padding:14px 20px; box-shadow:0 20px 40px rgba(0,0,0,0.35); text-align:center;\n  }\n  .float-badge-v2 strong{ display:block; font-family:'Barlow Condensed',sans-serif; font-weight:800; font-size:24px; }\n  .float-badge-v2 span{ font-size:10px; font-weight:700; }\n\n  /* ======================================================\n     CÓMO FUNCIONA — una sola tarjeta unificada\n  ====================================================== */\n  .funciona-v2-wrap{ margin-top:-46px; position:relative; z-index:5; padding-bottom:0; }\n  .funciona-v2-card{\n    background:var(--black-2); border:1px solid var(--line); border-radius:var(--radius);\n    display:grid; grid-template-columns:0.8fr 1.2fr; overflow:hidden;\n    box-shadow:0 30px 60px rgba(0,0,0,0.35);\n  }\n  .funciona-v2-photo{\n    position:relative; min-height:280px; background-size:cover; background-position:center;\n  }\n  .funciona-v2-photo::after{ content:''; position:absolute; inset:0; background:linear-gradient(180deg, rgba(10,10,12,0.05), rgba(10,10,12,0.7)); }\n  .funciona-v2-photo-label{ position:absolute; left:22px; bottom:22px; z-index:2; display:flex; align-items:center; gap:10px; color:var(--white); }\n  .funciona-v2-photo-label .play{ width:38px; height:38px; border-radius:50%; background:var(--yellow); color:var(--black); display:flex; align-items:center; justify-content:center; flex:none; }\n  .funciona-v2-photo-label strong{ font-size:14px; font-weight:700; }\n  .funciona-v2-cols{ display:grid; grid-template-columns:repeat(3,1fr); }\n  .funciona-v2-col{ padding:34px 24px; border-left:1px solid var(--line); }\n  .funciona-v2-col:first-child{ border-left:none; }\n  .funciona-v2-col .ic{ width:38px; height:38px; border-radius:50%; background:rgba(252,184,19,0.14); color:var(--yellow); display:flex; align-items:center; justify-content:center; margin-bottom:16px; }\n  .funciona-v2-col h4{ font-family:'Inter',sans-serif; font-weight:700; text-transform:none; font-size:14.5px; color:var(--white); margin-bottom:8px; line-height:1.25; }\n  .funciona-v2-col p{ font-size:12px; color:var(--muted); line-height:1.5; }\n\n  /* ======================================================\n     NOSOTROS v2\n  ====================================================== */\n  .nosotros-v2{ background:var(--paper); color:var(--black); padding-top:150px; }\n  .nosotros-v2-grid{ display:grid; grid-template-columns:0.85fr 1.15fr; gap:60px; align-items:center; }\n  .nosotros-v2-photo-wrap{ position:relative; }\n  .nosotros-v2-photo{ border-radius:var(--radius); overflow:hidden; }\n  .nosotros-v2-photo img{ width:100%; display:block; }\n  .nosotros-v2-tag{\n    position:absolute; left:24px; bottom:-22px;\n    background:var(--white); border:1px solid var(--line-dark); color:var(--black);\n    border-radius:12px; padding:12px 18px; font-size:12.5px; font-weight:700;\n    box-shadow:0 16px 30px rgba(0,0,0,0.12); display:flex; align-items:center; gap:8px;\n  }\n  .nosotros-v2-tag .ic{ width:24px; height:24px; border-radius:50%; background:var(--yellow); color:var(--black); display:flex; align-items:center; justify-content:center; flex:none; }\n  .nosotros-v2-eyebrow{\n    display:inline-block; background:var(--line-dark); color:var(--purple);\n    font-size:11.5px; font-weight:700; padding:6px 14px; border-radius:100px; margin-bottom:18px;\n  }\n  .nosotros-v2 h2{ color:var(--black); font-size:clamp(28px,3.6vw,40px); margin-bottom:22px; }\n  .nosotros-v2-mission-row{ display:grid; grid-template-columns:0.85fr 2fr; gap:18px; margin-bottom:26px; align-items:start; }\n  .nosotros-v2-mission-label{ display:flex; align-items:center; gap:9px; }\n  .nosotros-v2-mission-label .ic{ width:28px; height:28px; border-radius:9px; background:var(--yellow); color:var(--black); display:flex; align-items:center; justify-content:center; flex:none; }\n  .nosotros-v2-mission-label span{ font-size:13px; font-weight:700; color:var(--black); }\n  .nosotros-v2-mission-row p{ font-size:13.5px; color:var(--muted-2); line-height:1.6; }\n  .nosotros-v2-bar{\n    background:var(--black); border-radius:100px; padding:8px 8px 8px 22px;\n    display:flex; align-items:center; justify-content:space-between; gap:16px;\n  }\n  .nosotros-v2-bar-text{ display:flex; align-items:center; gap:10px; }\n  .nosotros-v2-bar-text .ck{ width:20px; height:20px; border-radius:50%; background:var(--yellow); color:var(--black); display:flex; align-items:center; justify-content:center; flex:none; font-size:11px; font-weight:800; }\n  .nosotros-v2-bar-text span{ font-size:12.5px; color:var(--ink); font-weight:500; }\n\n  /* ======================================================\n     STATS v2\n  ====================================================== */\n  .statsbar-v2{ background:var(--paper); color:var(--black); padding:70px 0 90px; }\n  .statsbar-v2-grid{ display:grid; grid-template-columns:repeat(4,1fr); gap:30px; }\n  .statsbar-v2-item{ border-top:3px solid var(--yellow); padding-top:16px; }\n  .statsbar-v2-item strong{ font-family:'Barlow Condensed',sans-serif; font-weight:800; font-size:42px; color:var(--black); white-space:nowrap; display:inline-block; }\n  .statsbar-v2-item strong .plus{ color:var(--yellow); display:inline; font-size:0.65em; vertical-align:top; }\n  .statsbar-v2-item span{ display:block; font-size:12.5px; color:var(--muted-2); line-height:1.4; max-width:190px; margin-top:6px; }\n\n  /* ======================================================\n     SERVICIOS v2 — chip compacto\n  ====================================================== */\n  .serv-v2{ background:var(--white); color:var(--black); }\n  .serv-v2-head{ display:flex; justify-content:space-between; align-items:flex-end; gap:32px; margin-bottom:44px; flex-wrap:wrap; }\n  .serv-v2-head .eyebrow{ color:var(--purple); }\n  .serv-v2-head .eyebrow::before{ background:var(--purple); }\n  .serv-v2-head h2{ font-size:clamp(28px,3.6vw,40px); color:var(--black); max-width:480px; }\n  .serv-v2-head p{ color:var(--muted-2); font-size:14px; max-width:260px; line-height:1.6; }\n  .serv-v2-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:22px; }\n  .serv-v2-card{ position:relative; border-radius:var(--radius); overflow:hidden; aspect-ratio:4/5; background-size:cover; background-position:center; }\n  .serv-v2-chip{\n    position:absolute; left:16px; bottom:16px; z-index:2;\n    background:rgba(10,10,12,0.85); backdrop-filter:blur(4px);\n    border-radius:100px; padding:8px 16px 8px 8px;\n    display:flex; align-items:center; gap:10px;\n  }\n  .serv-v2-chip .ic{ width:32px; height:32px; border-radius:50%; background:var(--yellow); color:var(--black); display:flex; align-items:center; justify-content:center; flex:none; }\n  .serv-v2-chip strong{ display:block; font-size:12.5px; font-weight:700; color:var(--white); line-height:1.2; }\n  .serv-v2-chip span{ font-size:10px; color:var(--muted); }\n\n  @media (max-width: 900px){\n    .nav-v2-pill{ display:none; }\n    .hero-v2-grid{ grid-template-columns:1fr; }\n    .phone-stage-v2{ height:420px; margin-top:20px; }\n    .phone-v2{ width:170px; height:350px; }\n    .phone-v2-a{ left:60px; }\n    .phone-v2-b{ left:170px; top:30px; }\n    .phone-v2-c{ display:none; }\n    .funciona-v2-card{ grid-template-columns:1fr; }\n    .funciona-v2-cols{ grid-template-columns:1fr; }\n    .funciona-v2-col{ border-left:none; border-top:1px solid var(--line); }\n    .funciona-v2-col:first-child{ border-top:none; }\n    .nosotros-v2{ padding-top:70px; }\n    .nosotros-v2-grid{ grid-template-columns:1fr; }\n    .nosotros-v2-mission-row{ grid-template-columns:1fr; }\n    .statsbar-v2-grid{ grid-template-columns:1fr 1fr; }\n    .serv-v2-grid{ grid-template-columns:1fr; }\n  }\n";

export default function HomePage() {
  const pageRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const root = pageRef.current;
    if (!root) return;

    const revealElements = root.querySelectorAll<HTMLElement>(".reveal");
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.1 }
    );

    revealElements.forEach((element) => observer.observe(element));

    const year = root.querySelector<HTMLElement>("#year");
    if (year) year.textContent = String(new Date().getFullYear());

    return () => observer.disconnect();
  }, []);

  return (
    <>
      <link rel="preconnect" href="https://fonts.googleapis.com" />
      <link rel="preconnect" href="https://fonts.gstatic.com" crossOrigin="anonymous" />
      <style dangerouslySetInnerHTML={{ __html: pageStyles }} />
      <div ref={pageRef} dangerouslySetInnerHTML={{ __html: pageMarkup }} />
    </>
  );
}
